async function main() {
  console.log(`Updating season playlist links for ${UAAP_SEASON_PLAYLISTS.length} UAAP seasons...`);
  for (const s of UAAP_SEASON_PLAYLISTS) {
    const { error } = await supabase
      .from("seasons")
      .update({ watch_url: s.watchUrl, watch_label: s.watchLabel })
      .eq("id", s.seasonId);
    if (error) {
      throw new Error(`Failed updating season ${s.seasonId}: ${error.message}`);
    }
  }

  console.log(`Updating game YouTube links for ${UAAP_GAME_YOUTUBE_LINKS.length} UAAP games...`);
  let updated = 0;
  for (const item of UAAP_GAME_YOUTUBE_LINKS) {
    const { data, error } = await supabase
      .from("games")
      .update({
        replay_url: item.replayUrl,
        replay_kind: item.replayKind,
        replay_label: item.replayLabel,
      })
      .eq("id", item.gameId)
      .select("id");
    if (error) {
      throw new Error(`Failed updating game ${item.gameId}: ${error.message}`);
    }
    if (!data?.length) {
      console.warn(`Warning: game ${item.gameId} not found in DB`);
    } else {
      updated++;
    }
  }

  console.log(`Successfully updated ${updated}/${UAAP_GAME_YOUTUBE_LINKS.length} UAAP game YouTube links!`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
